// src/api/auth/loginAPI.js
import axios_api from "../axios";
import { apiPath, IS_DEMO } from "../config";

const host = apiPath("/login");

export const LoginAPI = async (loginData) => {
  try {
    if (IS_DEMO) {
      // 데모는 무조건 통과. UI에서 쿠키/리덕스만 맞춰.
      return { token: "demo-token", user: { name: "demo" } };
    }
    const res = await axios_api.post(host, {
      loginId:  String(loginData.loginId  || "").trim(),
      password: String(loginData.password || ""),
    });
    return res.data;
  } catch (err) {
    console.error("로그인 실패:", err?.response?.data || err.message);
    return { error: true, message: err?.response?.data?.message || "LOGIN_FAILED" };
  }
};
